}

func TestAssuranceWrongContextLogicalDeadline(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
