		"node_id":       uint64(2),
		"leader_id":     uint64(1),
		"ctx_low":       ctxA.Low,
		"ctx_high":      ctxA.High,
		"deadline_tick": uint64(50),
	})

	heartbeatB, ok := findMessage(leaderMessagesB, pb.Heartbeat, 3, ctxB.Low)
	if !ok {
		t.Fatalf("no heartbeat carrying the later context was sent to node 3; messages=%+v", leaderMessagesB)
	}
	confirmationB := c.deliver(heartbeatB)
	leaderReplies := c.deliverTo(1, confirmationB)
	node2Reply, ok := findMessage(leaderReplies, pb.ReadIndexResp, 2, 0)
	if !ok {
		t.Fatalf("no ReadIndex response was produced for node 2; messages=%+v", leaderReplies)
	}
	_ = c.deliver(node2Reply)
	reads2.addReady(c.ready[2])
	batchBefore, existsBefore := reads2.batches[ctxA]
	batchIndex := uint64(0)
	if existsBefore {
		batchIndex = batchBefore.index
	}
	appliedIndex := uint64(0)
	if len(c.ready[2]) > 0 {
		appliedIndex = c.ready[2][0].Index
	}
	reads2.applied(appliedIndex)
	completedBeforeDeadline := 0
	select {
	case <-req2.CompletedC:
		completedBeforeDeadline = 1
	default:
	}

	// Advance the logical clock past the caller's deadline without sleeping,
	// then run the pending-read GC path.
	reads2.tick(51)
