			"request_id":        tc.id,
			"node_id":           uint64(100),
			"target_kind":       tc.kind,
			"target":            tc.addr,
			"expected":          tc.want,
			"expected_retained": !tc.want,
		})
		accepted := m.handleConfigChange(pb.ConfigChange{
			Type:    pb.AddNode,
			NodeID:  100,
			Address: tc.addr,
		}, 1000)
		_, stillObserver := m.members.Observers[100]
		emitPromotionAssuranceEvent(t, map[string]interface{}{
