	reads2.add(ctxA, []*RequestState{req2})
	reads3.add(ctxB, []*RequestState{req3})

	c.peers[2].ReadIndex(ctxA)
	_ = c.deliverTo(1, c.pump(2))
	c.peers[3].ReadIndex(ctxB)
	leaderMessagesB := c.deliverTo(1, c.pump(3))
	emitNodeHostAssuranceEvent(t, map[string]interface{}{
		"event":         "timeout_readindex_requested",
		"request_id":    "timeout-node2-A",
		"node_id":       uint64(2),
		"leader_id":     uint64(1),
		"ctx_low":       ctxA.Low,
		"ctx_high":      ctxA.High,
		"deadline_tick": uint64(50),
	})

	heartbeatB, ok := findMessage(leaderMessagesB, pb.Heartbeat, 3, ctxB.Low)
	if !ok {
		t.Fatalf("no heartbeat carrying the later context was sent to node 3; messages=%+v", leaderMessagesB)
	}
	confirmationB := c.deliver(heartbeatB)
	leaderReplies := c.deliverTo(1, confirmationB)
	node2Reply, ok := findMessage(leaderReplies, pb.ReadIndexResp, 2, 0)
	if !ok {
		t.Fatalf("no ReadIndex response was produced for node 2; messages=%+v", leaderReplies)
	}
	_ = c.deliver(node2Reply)
	reads2.addReady(c.ready[2])
	batchBefore, existsBefore := reads2.batches[ctxA]
	batchIndex := uint64(0)
	if existsBefore {
		batchIndex = batchBefore.index
	}
	appliedIndex := uint64(0)
	if len(c.ready[2]) > 0 {
		appliedIndex = c.ready[2][0].Index
	}
	reads2.applied(appliedIndex)
	completedBeforeDeadline := 0
	select {
	case <-req2.CompletedC:
		completedBeforeDeadline = 1
	default:
	}

	// Advance the logical clock past the caller's deadline without sleeping,
	// then run the pending-read GC path.
	reads2.tick(51)
	reads2.applied(appliedIndex)
	var result RequestResult
	select {
	case result = <-req2.CompletedC:
	default:
		t.Fatal("request did not receive a timeout result after its logical deadline")
	}
	_, stillExists := reads2.batches[ctxA]
	emitNodeHostAssuranceEvent(t, map[string]interface{}{
		"event":                        "wrong_context_timeout_state",
		"request_id":                   "timeout-node2-A",
		"trigger_from":                 uint64(3),
		"trigger_ctx_low":              ctxB.Low,
		"response_ctx_low":             node2Reply.Hint,
		"original_batch_exists":        existsBefore,
		"original_batch_index":         batchIndex,
		"completed_before_deadline":    completedBeforeDeadline,
		"deadline_tick":                uint64(50),
		"advanced_tick":                uint64(51),
		"result_code":                  int(result.code),
		"result_code_name":             requestResultCodeName[result.code],
		"result_code_is_timeout":       result.code == requestTimeout,
		"batch_still_present_after_gc": stillExists,
	})
}

