// TestAssurancePeriodicHeartbeatReadIndexBatching exercises the leader's own
// periodic heartbeat instead of a harness-chosen delivery: two reads from two
// followers are queued, one leader tick makes the heartbeat carry the newest
// queued context, and the earlier requester receives the reply produced by
// that confirmation.
func TestAssurancePeriodicHeartbeatReadIndexBatching(t *testing.T) {
	c := newAssuranceCluster(t)
	for i := 0; i < 100 && c.commit[1] < uint64(4); i++ {
		c.peers[1].Tick()
		c.drain(c.pump(1))
	}
	if c.commit[1] < 4 {
		t.Fatalf("leader failed to commit its current-term no-op, commit=%d",
			c.commit[1])
	}

	pool := &sync.Pool{New: func() interface{} { return &RequestState{} }}
	reads2 := newPendingReadIndex(pool, newReadIndexQueue(16))
	reads3 := newPendingReadIndex(pool, newReadIndexQueue(16))
	req2, err := reads2.read(50)
	if err != nil {
		t.Fatalf("failed to create node 2 read: %v", err)
	}
	req3, err := reads3.read(50)
	if err != nil {
		t.Fatalf("failed to create node 3 read: %v", err)
	}
	ctxA := reads2.nextCtx()
	ctxB := reads3.nextCtx()
	reads2.add(ctxA, []*RequestState{req2})
	reads3.add(ctxB, []*RequestState{req3})

	// Both reads reach the leader through the real follower forwarding path.
	c.peers[2].ReadIndex(ctxA)
	_ = c.deliverTo(1, c.pump(2))
	c.peers[3].ReadIndex(ctxB)
	_ = c.deliverTo(1, c.pump(3))
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "readindex_queued",
		"request_id": "node2-read-A",
		"node_id":    uint64(2),
		"ctx_low":    ctxA.Low,
		"ctx_high":   ctxA.High,
	})
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":      "readindex_queued",
		"request_id": "node3-read-B",
		"node_id":    uint64(3),
		"ctx_low":    ctxB.Low,
		"ctx_high":   ctxB.High,
	})

	// A single leader tick makes the periodic heartbeat carry the newest
	// queued context; no message is reordered by the harness.
	c.peers[1].Tick()
	periodic := c.pump(1)
	heartbeat, ok := findAssuranceMessage(periodic, pb.Heartbeat, 3, ctxB.Low)
	if !ok {
		t.Fatalf("periodic heartbeat did not carry the newest queued context; messages=%+v",
			periodic)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":             "periodic_heartbeat_broadcast",
		"heartbeat_to":      heartbeat.To,
		"heartbeat_ctx_low": heartbeat.Hint,
		"earlier_ctx_low":   ctxA.Low,
		"newest_ctx_low":    ctxB.Low,
		"queued_reads":      2,
	})

	replies := c.deliverTo(1, c.deliver(heartbeat))
	node2Reply, ok := findAssuranceMessage(replies, pb.ReadIndexResp, 2, 0)
	if !ok {
		t.Fatalf("leader produced no ReadIndex response for node 2; messages=%+v",
			replies)
	}
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":              "readindex_reply",
		"request_id":         "node2-read-A",
		"reply_to":           node2Reply.To,
		"admitted_ctx_low":   ctxA.Low,
		"response_ctx_low":   node2Reply.Hint,
		"response_ctx_high":  node2Reply.HintHigh,
		"response_log_index": node2Reply.LogIndex,
	})

	_ = c.deliver(node2Reply)
	reads2.addReady(c.ready[2])
	batch, exists := reads2.batches[ctxA]
	batchIndex := uint64(0)
	if exists {
		batchIndex = batch.index
	}
	appliedIndex := uint64(0)
	if len(c.ready[2]) > 0 {
		appliedIndex = c.ready[2][0].Index
	}
	reads2.applied(appliedIndex)
	emitObserverEndpointEvent(t, map[string]interface{}{
		"event":                 "read_completion_state",
		"request_id":            "node2-read-A",
		"original_batch_exists": exists,
		"original_batch_index":  batchIndex,
		"ready_index":           appliedIndex,
		"applied_index":         appliedIndex,
		"completed_after_reply": completedFlag(req2),
	})
	_ = req3
}

// TestAssurancePeriodicHeartbeatReadIndexControl queues a single read so the
// periodic heartbeat carries that read's own context, and checks that the same
// tick-driven path completes it.
func TestAssurancePeriodicHeartbeatReadIndexControl(t *testing.T) {
